-- Reviewed course tuition percentage creates gross accounting only.
-- Session allocations and collected-receipt bases have separate source ownership.
CREATE TABLE public.payroll_tuition_collection_accruals(
 academy_id uuid NOT NULL,id uuid NOT NULL,engagement_id uuid NOT NULL,work_version integer NOT NULL,terms_version integer NOT NULL,person_id uuid NOT NULL,hub_id uuid,
 sequence integer NOT NULL CHECK(sequence>0),entitlement_numerator numeric NOT NULL CHECK(entitlement_numerator>=0 AND entitlement_numerator=trunc(entitlement_numerator)),entitlement_denominator numeric NOT NULL CHECK(entitlement_denominator>0 AND entitlement_denominator=trunc(entitlement_denominator)),journal_id uuid,component_code text NOT NULL,invoice_id uuid NOT NULL,plan_id uuid NOT NULL,basis text NOT NULL CHECK(basis IN('period_collected_net','period_collected_gross')),
 earned_on date NOT NULL,due_on date NOT NULL,posted_on date NOT NULL,currency_id uuid NOT NULL,currency_version integer NOT NULL,unit_scale integer NOT NULL CHECK(unit_scale BETWEEN 0 AND 18),amount_minor numeric NOT NULL CHECK(amount_minor>=0 AND amount_minor=trunc(amount_minor) AND amount_minor<1e38),
 expense_account uuid NOT NULL,expense_version integer NOT NULL,liability_account uuid NOT NULL,liability_version integer NOT NULL,period_id uuid NOT NULL,period_version integer NOT NULL,
 input jsonb NOT NULL,source_snapshot jsonb NOT NULL CHECK(jsonb_typeof(source_snapshot)='object' AND octet_length(source_snapshot::text)<=131072),approval_id uuid NOT NULL,created_by uuid NOT NULL,void_id uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(academy_id,id),CHECK((amount_minor=0 AND journal_id IS NULL) OR(amount_minor>0 AND journal_id IS NOT NULL AND journal_id=id)),CHECK(earned_on BETWEEN DATE '1900-01-01' AND DATE '9999-12-31' AND due_on BETWEEN DATE '1900-01-01' AND DATE '9999-12-31' AND posted_on BETWEEN earned_on AND DATE '9999-12-31'),
 FOREIGN KEY(academy_id,invoice_id) REFERENCES public.tuition_invoices(academy_id,id),FOREIGN KEY(academy_id,engagement_id,terms_version) REFERENCES public.work_engagement_revisions(academy_id,engagement_id,version),FOREIGN KEY(academy_id,person_id) REFERENCES public.people(academy_id,id),FOREIGN KEY(academy_id,hub_id) REFERENCES public.hubs(academy_id,id),
 FOREIGN KEY(academy_id,currency_id,currency_version) REFERENCES public.finance_currency_revisions(academy_id,currency_id,version),FOREIGN KEY(academy_id,expense_account,expense_version) REFERENCES public.finance_account_revisions(academy_id,account_id,version),FOREIGN KEY(academy_id,liability_account,liability_version) REFERENCES public.finance_account_revisions(academy_id,account_id,version),FOREIGN KEY(academy_id,period_id,period_version) REFERENCES public.finance_period_revisions(academy_id,period_id,version),
 FOREIGN KEY(academy_id,approval_id) REFERENCES public.approval_requests(academy_id,id),FOREIGN KEY(academy_id,created_by) REFERENCES public.people(academy_id,id),FOREIGN KEY(academy_id,journal_id) REFERENCES public.finance_journals(academy_id,id) DEFERRABLE INITIALLY DEFERRED
);
-- Identity is independent of component label, terms version, quantity and date.
ALTER TABLE public.payroll_tuition_collection_accruals ADD CONSTRAINT tuition_collection_plan FOREIGN KEY(academy_id,plan_id) REFERENCES public.tuition_plans(academy_id,id);
CREATE UNIQUE INDEX tuition_collection_sequence ON public.payroll_tuition_collection_accruals(academy_id,engagement_id,plan_id,sequence);
CREATE INDEX tuition_collection_live_source ON public.payroll_tuition_collection_accruals(academy_id,engagement_id,plan_id,sequence) WHERE void_id IS NULL;
CREATE INDEX tuition_collection_worker_due ON public.payroll_tuition_collection_accruals(academy_id,person_id,due_on,id);
CREATE TABLE public.payroll_tuition_collection_voids(
 academy_id uuid NOT NULL,id uuid NOT NULL,accrual_id uuid NOT NULL,journal_id uuid,posted_on date NOT NULL,input jsonb NOT NULL,source_snapshot jsonb NOT NULL CHECK(jsonb_typeof(source_snapshot)='object' AND octet_length(source_snapshot::text)<=131072),approval_id uuid NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(academy_id,id),UNIQUE(academy_id,accrual_id),UNIQUE(academy_id,id,accrual_id),FOREIGN KEY(academy_id,accrual_id) REFERENCES public.payroll_tuition_collection_accruals(academy_id,id),FOREIGN KEY(academy_id,approval_id) REFERENCES public.approval_requests(academy_id,id),FOREIGN KEY(academy_id,created_by) REFERENCES public.people(academy_id,id),FOREIGN KEY(academy_id,journal_id) REFERENCES public.finance_journals(academy_id,id) DEFERRABLE INITIALLY DEFERRED
);
ALTER TABLE public.payroll_tuition_collection_accruals ADD CONSTRAINT tuition_collection_void_identity FOREIGN KEY(academy_id,void_id,id) REFERENCES public.payroll_tuition_collection_voids(academy_id,id,accrual_id) DEFERRABLE INITIALLY DEFERRED;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['payroll_tuition_collection_accruals','payroll_tuition_collection_voids'] LOOP
 EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY tenant_boundary ON public.%I USING(academy_id=nullif(current_setting(''app.academy_id'',true),'''')::uuid) WITH CHECK(academy_id=nullif(current_setting(''app.academy_id'',true),'''')::uuid)',t);
 EXECUTE format('CREATE TRIGGER tuition_collection_write BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH STATEMENT EXECUTE FUNCTION public.guard_expense_commitment_write()',t);
 EXECUTE format('GRANT SELECT ON public.%I TO kavosh_runtime',t);
END LOOP;END $$;
-- All searchable financial metadata is derived by the guarded trigger, not
-- supplied by the application or an INSERT with a caller-chosen amount.
GRANT INSERT(academy_id,id,input,source_snapshot,approval_id,created_by) ON public.payroll_tuition_collection_accruals TO kavosh_runtime;
GRANT UPDATE(void_id) ON public.payroll_tuition_collection_accruals TO kavosh_runtime;
GRANT INSERT(academy_id,id,accrual_id,input,source_snapshot,approval_id,created_by) ON public.payroll_tuition_collection_voids TO kavosh_runtime;

CREATE TABLE public.payroll_tuition_collection_receipts(
 academy_id uuid NOT NULL,accrual_id uuid NOT NULL,engagement_id uuid NOT NULL,plan_id uuid NOT NULL,receipt_id uuid NOT NULL,release_id uuid,
 PRIMARY KEY(academy_id,accrual_id,receipt_id),FOREIGN KEY(academy_id,accrual_id) REFERENCES public.payroll_tuition_collection_accruals(academy_id,id),FOREIGN KEY(academy_id,receipt_id) REFERENCES public.tuition_receipts(academy_id,id),FOREIGN KEY(academy_id,release_id,accrual_id) REFERENCES public.payroll_tuition_collection_voids(academy_id,id,accrual_id) DEFERRABLE INITIALLY DEFERRED
);
CREATE UNIQUE INDEX tuition_collection_receipt_live ON public.payroll_tuition_collection_receipts(academy_id,engagement_id,receipt_id) WHERE release_id IS NULL;
ALTER TABLE public.payroll_tuition_collection_receipts ENABLE ROW LEVEL SECURITY;ALTER TABLE public.payroll_tuition_collection_receipts FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_boundary ON public.payroll_tuition_collection_receipts USING(academy_id=nullif(current_setting('app.academy_id',true),'')::uuid) WITH CHECK(academy_id=nullif(current_setting('app.academy_id',true),'')::uuid);
CREATE TRIGGER collection_receipt_write BEFORE INSERT OR UPDATE OR DELETE ON public.payroll_tuition_collection_receipts FOR EACH STATEMENT EXECUTE FUNCTION public.guard_expense_commitment_write();
GRANT SELECT ON public.payroll_tuition_collection_receipts TO kavosh_runtime;GRANT INSERT(academy_id,accrual_id,receipt_id) ON public.payroll_tuition_collection_receipts TO kavosh_runtime;GRANT UPDATE(release_id) ON public.payroll_tuition_collection_receipts TO kavosh_runtime;
CREATE FUNCTION public.collection_receipt_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE a record;BEGIN
 SELECT * INTO a FROM public.payroll_tuition_collection_accruals WHERE academy_id=NEW.academy_id AND id=NEW.accrual_id;
 IF TG_OP='UPDATE' THEN IF to_jsonb(NEW)-'release_id' IS DISTINCT FROM to_jsonb(OLD)-'release_id' OR OLD.release_id IS NOT NULL OR NEW.release_id IS NULL OR a.void_id IS DISTINCT FROM NEW.release_id THEN RAISE EXCEPTION 'COLLECTION_RECEIPT_RELEASE_INVALID' USING ERRCODE='23514';END IF;RETURN NEW;END IF;
 IF a.id IS NULL OR a.void_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(a.source_snapshot#>'{collection,receipts}') x WHERE x->>'id'=NEW.receipt_id::text) THEN RAISE EXCEPTION 'COLLECTION_RECEIPT_SOURCE_REQUIRED' USING ERRCODE='23514';END IF;NEW.engagement_id=a.engagement_id;NEW.plan_id=a.plan_id;NEW.release_id=NULL;RETURN NEW;
END $$;
CREATE TRIGGER collection_receipt_guard BEFORE INSERT OR UPDATE ON public.payroll_tuition_collection_receipts FOR EACH ROW EXECUTE FUNCTION public.collection_receipt_guard();
REVOKE ALL ON FUNCTION public.collection_receipt_guard() FROM PUBLIC;

CREATE FUNCTION public.tuition_collection_input_valid(i jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ DECLARE k text;r jsonb;d date;keys text[]:=ARRAY['engagement','termsVersion','componentCode','invoiceId','receiptIds','collectionFrom','collectionThrough','compensationOn','earnedOn','dueOn','postedOn','period','expenseAccount','liabilityAccount','earningReview','taxReview','reason'];BEGIN
 IF jsonb_typeof(i) IS DISTINCT FROM 'object' OR NOT(i ?& keys) OR i-keys<>'{}'::jsonb OR octet_length(i::text)>65536 THEN RETURN false;END IF;
 FOREACH k IN ARRAY ARRAY['earningReview','taxReview','reason'] LOOP IF jsonb_typeof(i->k) IS DISTINCT FROM 'string' OR length(btrim(i->>k)) NOT BETWEEN 1 AND 2000 THEN RETURN false;END IF;END LOOP;
 IF jsonb_typeof(i->'componentCode') IS DISTINCT FROM 'string' OR i->>'componentCode'!~'^[A-Z0-9][A-Z0-9._-]{0,63}$' OR jsonb_typeof(i->'invoiceId') IS DISTINCT FROM 'string' OR(i->>'invoiceId')::uuid::text IS DISTINCT FROM i->>'invoiceId' THEN RETURN false;END IF;
 IF jsonb_typeof(i->'receiptIds') IS DISTINCT FROM 'array' OR jsonb_array_length(i->'receiptIds') NOT BETWEEN 1 AND 200 OR(SELECT count(DISTINCT x#>>'{}') FROM jsonb_array_elements(i->'receiptIds') x)<>jsonb_array_length(i->'receiptIds') THEN RETURN false;END IF;FOR r IN SELECT value FROM jsonb_array_elements(i->'receiptIds') LOOP IF jsonb_typeof(r) IS DISTINCT FROM 'string' OR(r#>>'{}')::uuid::text IS DISTINCT FROM r#>>'{}' THEN RETURN false;END IF;END LOOP;
 FOREACH k IN ARRAY ARRAY['engagement','period','expenseAccount','liabilityAccount'] LOOP r=i->k;IF jsonb_typeof(r) IS DISTINCT FROM 'object' OR NOT(r ?& ARRAY['id','version']) OR r-ARRAY['id','version']<>'{}'::jsonb OR jsonb_typeof(r->'id') IS DISTINCT FROM 'string' OR(r->>'id')::uuid::text IS DISTINCT FROM r->>'id' OR jsonb_typeof(r->'version') IS DISTINCT FROM 'number' OR(r->>'version')::numeric NOT BETWEEN 1 AND 2147483647 OR(r->>'version')::numeric<>trunc((r->>'version')::numeric) THEN RETURN false;END IF;END LOOP;
 IF jsonb_typeof(i->'termsVersion') IS DISTINCT FROM 'number' OR(i->>'termsVersion')::numeric NOT BETWEEN 1 AND 2147483647 OR(i->>'termsVersion')::numeric<>trunc((i->>'termsVersion')::numeric) THEN RETURN false;END IF;
 FOREACH k IN ARRAY ARRAY['earnedOn','dueOn','postedOn','collectionFrom','collectionThrough','compensationOn'] LOOP IF jsonb_typeof(i->k) IS DISTINCT FROM 'string' OR i->>k!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RETURN false;END IF;d=(i->>k)::date;IF d NOT BETWEEN DATE '1900-01-01' AND DATE '9999-12-31' THEN RETURN false;END IF;END LOOP;
 RETURN(i->>'postedOn')::date>=(i->>'earnedOn')::date AND(i->>'earnedOn')::date>=(i->>'compensationOn')::date AND(i->>'collectionThrough')::date BETWEEN(i->>'collectionFrom')::date AND(i->>'collectionFrom')::date+365;
 EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow THEN RETURN false;
END $$;
CREATE FUNCTION public.tuition_collection_accrual_source(i jsonb,p_exclude uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog SET DateStyle='ISO,YMD' AS $$
DECLARE tenant uuid:=nullif(current_setting('app.academy_id',true),'')::uuid;s jsonb;w jsonb;c jsonb;r record;t record;a record;prior record;receipts jsonb;received numeric;new_num numeric;den numeric;amount numeric;floor_on date;seq integer;BEGIN
 s=public.payroll_adjustment_source((i#>>'{engagement,id}')::uuid,(i->>'compensationOn')::date,(i#>>'{expenseAccount,id}')::uuid,(i#>>'{liabilityAccount,id}')::uuid,(i#>>'{period,id}')::uuid);IF s IS NULL THEN RETURN NULL;END IF;w=s->'work';
 IF(w->>'headerVersion')::integer<>(i#>>'{engagement,version}')::integer OR(w->>'termsVersion')::integer<>(i->>'termsVersion')::integer THEN RETURN jsonb_build_object('unavailable','WORK_TERMS_CHANGED');END IF;
 IF w->'active'<>'true'::jsonb OR w->>'classification' NOT IN('employee','contractor') OR(i->>'compensationOn')::date<(w->>'startsOn')::date OR(w->>'endsOn' IS NOT NULL AND(i->>'compensationOn')::date>(w->>'endsOn')::date) THEN RETURN jsonb_build_object('unavailable','EFFECTIVE_COMPENSATED_WORK_REQUIRED');END IF;
 SELECT * INTO r FROM public.work_engagement_revisions WHERE academy_id=tenant AND engagement_id=(w->>'id')::uuid AND version=(w->>'termsVersion')::integer;
 SELECT value INTO c FROM jsonb_array_elements(r.components) WHERE value->>'code'=i->>'componentCode' AND value->>'kind'='tuition_percentage' AND(i->>'compensationOn')::date>=(value->>'from')::date AND(value->>'through' IS NULL OR(i->>'compensationOn')::date<=(value->>'through')::date);
 IF c IS NULL OR c->>'basis' NOT IN('period_collected_net','period_collected_gross') THEN RETURN jsonb_build_object('unavailable','COLLECTION_PERCENTAGE_COMPONENT_REQUIRED');END IF;
 SELECT inv.id,inv.plan_id,inv.plan_version,inv.student_id,inv.class_id,inv.hub_id,inv.credit_id,p.currency_id,p.unit_scale,v.net_minor,v.gross_minor INTO t FROM public.tuition_invoices inv JOIN public.tuition_plans p ON p.academy_id=inv.academy_id AND p.id=inv.plan_id JOIN public.tuition_plan_revisions v ON v.academy_id=inv.academy_id AND v.plan_id=inv.plan_id AND v.version=inv.plan_version WHERE inv.academy_id=tenant AND inv.id=(i->>'invoiceId')::uuid;
 IF t.id IS NULL THEN RETURN NULL;END IF;IF t.credit_id IS NOT NULL THEN RETURN jsonb_build_object('unavailable','CREDITED_TUITION_SOURCE_REQUIRES_REVIEW');END IF;
 IF t.currency_id::text<>w->>'currencyId' OR t.hub_id IS DISTINCT FROM(w->>'hubId')::uuid OR t.gross_minor<=0 THEN RETURN jsonb_build_object('unavailable','TUITION_COLLECTION_SOURCE_MISMATCH');END IF;
 SELECT cs.id,cs.class_id,cs.person_id,v.version,v.definition INTO a FROM public.class_staff cs JOIN public.class_staff_revisions v ON v.academy_id=cs.academy_id AND v.assignment_id=cs.id AND v.version=(c#>>'{assignment,version}')::integer WHERE cs.academy_id=tenant AND cs.id=(c#>>'{assignment,id}')::uuid;
 IF a.id IS NULL OR a.class_id<>t.class_id OR a.person_id::text IS DISTINCT FROM w->>'personId' OR a.definition->'active' IS DISTINCT FROM 'true'::jsonb OR(i->>'compensationOn')::date<(a.definition->>'startsOn')::date OR(a.definition->>'endsOn' IS NOT NULL AND(i->>'compensationOn')::date>(a.definition->>'endsOn')::date) THEN RETURN jsonb_build_object('unavailable','TUITION_COLLECTION_ASSIGNMENT_REQUIRED');END IF;
 IF EXISTS(SELECT 1 FROM public.payroll_tuition_course_accruals z WHERE z.academy_id=tenant AND z.engagement_id=(w->>'id')::uuid AND z.plan_id=t.plan_id AND z.void_id IS NULL) OR EXISTS(SELECT 1 FROM public.payroll_tuition_session_accruals z WHERE z.academy_id=tenant AND z.engagement_id=(w->>'id')::uuid AND z.plan_id=t.plan_id AND z.void_id IS NULL) THEN RETURN jsonb_build_object('unavailable','TUITION_EARNING_BASIS_CONFLICT');END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',q.id,'receivedOn',q.received_on::text,'amountMinor',q.amount_minor::text) ORDER BY q.id),'[]'::jsonb),coalesce(sum(q.amount_minor),0) INTO receipts,received FROM public.tuition_receipts q WHERE q.academy_id=tenant AND q.invoice_id=t.id AND q.id IN(SELECT x::uuid FROM jsonb_array_elements_text(i->'receiptIds') x) AND q.reversal_id IS NULL AND q.received_on BETWEEN(i->>'collectionFrom')::date AND(i->>'collectionThrough')::date AND q.received_on<=(i->>'earnedOn')::date;
 IF jsonb_array_length(receipts)<>jsonb_array_length(i->'receiptIds') THEN RETURN jsonb_build_object('unavailable','ACTIVE_SELECTED_COLLECTION_RECEIPTS_REQUIRED');END IF;
 IF EXISTS(SELECT 1 FROM public.payroll_tuition_collection_receipts q WHERE q.academy_id=tenant AND q.engagement_id=(w->>'id')::uuid AND q.receipt_id IN(SELECT x::uuid FROM jsonb_array_elements_text(i->'receiptIds') x) AND q.release_id IS NULL AND(p_exclude IS NULL OR q.accrual_id<>p_exclude)) THEN RETURN jsonb_build_object('unavailable','TUITION_RECEIPT_ALREADY_ACCRUED');END IF;
 den=trunc(t.gross_minor*1000000*power(10::numeric,t.unit_scale));
 SELECT count(*) n,coalesce(sum(z.entitlement_numerator),0) numerator,coalesce(sum(z.amount_minor),0) gross,coalesce(max(z.sequence),0) last_sequence,max(z.posted_on) last_posted,bool_and(z.entitlement_denominator=den AND z.unit_scale=(w->>'unitScale')::integer AND z.invoice_id=t.id) compatible INTO prior FROM public.payroll_tuition_collection_accruals z WHERE z.academy_id=tenant AND z.engagement_id=(w->>'id')::uuid AND z.plan_id=t.plan_id AND z.void_id IS NULL AND(p_exclude IS NULL OR z.id<>p_exclude);
 IF prior.n>1000 THEN RETURN jsonb_build_object('unavailable','TUITION_COLLECTION_REQUIRES_BACKGROUND_JOB');END IF;
 IF prior.compatible IS FALSE OR EXISTS(SELECT 1 FROM public.payroll_tuition_collection_receipts q JOIN public.payroll_tuition_collection_accruals z ON z.academy_id=q.academy_id AND z.id=q.accrual_id JOIN public.tuition_receipts rr ON rr.academy_id=q.academy_id AND rr.id=q.receipt_id WHERE z.academy_id=tenant AND z.engagement_id=(w->>'id')::uuid AND z.plan_id=t.plan_id AND z.void_id IS NULL AND rr.reversal_id IS NOT NULL AND(p_exclude IS NULL OR z.id<>p_exclude)) OR prior.gross<>div(2*prior.numerator+den,2*den) THEN RETURN jsonb_build_object('unavailable','COLLECTION_PRIOR_SOURCE_CORRECTION_REQUIRED');END IF;
 SELECT coalesce(max(z.sequence),0)+1 INTO seq FROM public.payroll_tuition_collection_accruals z WHERE z.academy_id=tenant AND z.engagement_id=(w->>'id')::uuid AND z.plan_id=t.plan_id AND(p_exclude IS NULL OR z.id<>p_exclude);
 SELECT greatest(prior.last_posted,max(q.posted_on)) INTO floor_on FROM(SELECT v.posted_on FROM public.payroll_tuition_collection_accruals z JOIN public.payroll_tuition_collection_voids v ON v.academy_id=z.academy_id AND v.id=z.void_id WHERE z.academy_id=tenant AND z.engagement_id=(w->>'id')::uuid AND z.plan_id=t.plan_id UNION ALL SELECT j.posted_on FROM public.payroll_tuition_course_accruals z JOIN public.finance_journals j ON j.academy_id=z.academy_id AND j.id=z.void_id WHERE z.academy_id=tenant AND z.engagement_id=(w->>'id')::uuid AND z.plan_id=t.plan_id UNION ALL SELECT j.posted_on FROM public.payroll_tuition_session_accruals z JOIN public.finance_journals j ON j.academy_id=z.academy_id AND j.id=z.void_id WHERE z.academy_id=tenant AND z.engagement_id=(w->>'id')::uuid AND z.plan_id=t.plan_id) q;
 new_num=trunc(received*(CASE WHEN c->>'basis'='period_collected_net' THEN t.net_minor ELSE t.gross_minor END)*((c->>'percent')::numeric*10000)*power(10::numeric,(w->>'unitScale')::integer));amount=div(2*(prior.numerator+new_num)+den,2*den)-prior.gross;
 RETURN jsonb_build_object('work',w,'accounting',s-'work','component',c,'tuition',jsonb_build_object('invoiceId',t.id,'planId',t.plan_id,'planVersion',t.plan_version,'studentId',t.student_id,'classId',t.class_id,'hubId',t.hub_id,'currencyId',t.currency_id,'unitScale',t.unit_scale,'netMinor',t.net_minor::text,'grossMinor',t.gross_minor::text,'assignmentId',a.id,'assignmentVersion',a.version,'assignment',a.definition),'collection',jsonb_build_object('sequence',seq,'receipts',receipts,'grossMinor',received::text,'numerator',new_num::text,'denominator',den::text,'priorNumerator',prior.numerator::text,'priorGrossMinor',prior.gross::text,'priorCount',prior.n,'roundingPolicy','exact_positive_integer_half_away_cumulative_prefix'),'grossMinor',amount::text,'releaseFloorOn',floor_on::text);
END $$;
CREATE FUNCTION public.tuition_collection_void_source(p_id uuid,p_period uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog SET DateStyle='ISO,YMD' AS $$ DECLARE tenant uuid:=nullif(current_setting('app.academy_id',true),'')::uuid;b record;s jsonb;BEGIN
 SELECT * INTO b FROM public.payroll_tuition_collection_accruals WHERE academy_id=tenant AND id=p_id;IF NOT FOUND THEN RETURN NULL;END IF;PERFORM public.lock_pay_period_work(b.engagement_id);SELECT * INTO b FROM public.payroll_tuition_collection_accruals WHERE academy_id=tenant AND id=p_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.payroll_tuition_collection_accruals z WHERE z.academy_id=tenant AND z.engagement_id=b.engagement_id AND z.plan_id=b.plan_id AND z.void_id IS NULL AND z.sequence>b.sequence) THEN RETURN jsonb_build_object('unavailable','COLLECTION_DEPENDENT_EARNINGS_REQUIRE_CORRECTION');END IF;
 s=public.payroll_adjustment_source(b.engagement_id,(b.input->>'compensationOn')::date,b.expense_account,b.liability_account,p_period);IF s IS NULL THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('before',jsonb_build_object('id',b.id,'engagementId',b.engagement_id,'personId',b.person_id,'hubId',b.hub_id,'voidId',b.void_id,'postedOn',b.posted_on::text,'grossMinor',b.amount_minor::text,'sequence',b.sequence),'current',s);
END $$;
CREATE FUNCTION public.tuition_collection_record_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE p record;s jsonb;w jsonb;target jsonb;e jsonb;l jsonb;a jsonb;BEGIN
 IF TG_OP='UPDATE' THEN IF OLD.void_id IS NOT NULL OR NEW.void_id IS NULL OR to_jsonb(NEW)-'void_id' IS DISTINCT FROM to_jsonb(OLD)-'void_id' THEN RAISE EXCEPTION 'TUITION_COLLECTION_ACCRUAL_IMMUTABLE' USING ERRCODE='23514';END IF;RETURN NEW;END IF;
 IF NOT public.tuition_collection_input_valid(NEW.input) THEN RAISE EXCEPTION 'TUITION_COLLECTION_INPUT_INVALID' USING ERRCODE='23514';END IF;
 s=public.tuition_collection_accrual_source(NEW.input,NEW.id);w=s->'work';SELECT * INTO p FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id;
 target=jsonb_build_object('all',false,'hubs','[]'::jsonb,'people',jsonb_build_array(jsonb_build_object('id',w->>'personId','hubId',w->'hubId')),'workContext',jsonb_build_object('personId',w->>'personId','hubId',w->'hubId'));
 IF s IS NULL OR s ? 'unavailable' OR p.id IS NULL OR p.status<>'pending' OR p.action IS DISTINCT FROM 'work.tuition_collection.record' OR p.target_id IS DISTINCT FROM NEW.id OR p.target_version IS DISTINCT FROM 0 OR p.privacy_capability IS DISTINCT FROM 'payroll-accruals.view' OR p.scope IS DISTINCT FROM target OR p.payload IS DISTINCT FROM NEW.input OR p.review_context IS DISTINCT FROM s OR NEW.source_snapshot IS DISTINCT FROM s OR NOT public.report_comment_human_verified(NEW.created_by) THEN RAISE EXCEPTION 'TUITION_COLLECTION_EXACT_REVIEW_REQUIRED' USING ERRCODE='23514';END IF;
 IF NEW.created_by=(w->>'personId')::uuid AND NOT EXISTS(SELECT 1 FROM public.academies WHERE id=NEW.academy_id AND master_person_id=NEW.created_by) THEN RAISE EXCEPTION 'BENEFICIARY_REVIEW_FORBIDDEN' USING ERRCODE='23514';END IF;
 IF s->>'releaseFloorOn' IS NOT NULL AND(NEW.input->>'postedOn')::date<(s->>'releaseFloorOn')::date THEN RAISE EXCEPTION 'TUITION_COLLECTION_CORRECTION_DATE_REQUIRED' USING ERRCODE='23514';END IF;
 NEW.engagement_id=(w->>'id')::uuid;NEW.work_version=(w->>'headerVersion')::integer;NEW.terms_version=(w->>'termsVersion')::integer;NEW.person_id=(w->>'personId')::uuid;NEW.hub_id=(w->>'hubId')::uuid;NEW.component_code=NEW.input->>'componentCode';NEW.invoice_id=(NEW.input->>'invoiceId')::uuid;NEW.plan_id=(s#>>'{tuition,planId}')::uuid;NEW.basis=s#>>'{component,basis}';NEW.earned_on=(NEW.input->>'earnedOn')::date;NEW.due_on=(NEW.input->>'dueOn')::date;NEW.posted_on=(NEW.input->>'postedOn')::date;
 NEW.sequence=(s#>>'{collection,sequence}')::integer;NEW.entitlement_numerator=(s#>>'{collection,numerator}')::numeric;NEW.entitlement_denominator=(s#>>'{collection,denominator}')::numeric;NEW.journal_id=CASE WHEN(s->>'grossMinor')::numeric>0 THEN NEW.id ELSE NULL END;
 NEW.currency_id=(w->>'currencyId')::uuid;NEW.currency_version=(w->>'currencyVersion')::integer;NEW.unit_scale=(w->>'unitScale')::integer;NEW.amount_minor=(s->>'grossMinor')::numeric;NEW.expense_account=(NEW.input#>>'{expenseAccount,id}')::uuid;NEW.expense_version=(NEW.input#>>'{expenseAccount,version}')::integer;NEW.liability_account=(NEW.input#>>'{liabilityAccount,id}')::uuid;NEW.liability_version=(NEW.input#>>'{liabilityAccount,version}')::integer;NEW.period_id=(NEW.input#>>'{period,id}')::uuid;NEW.period_version=(NEW.input#>>'{period,version}')::integer;NEW.created_at=clock_timestamp();
 SELECT value INTO e FROM jsonb_array_elements(s#>'{accounting,accounts}') WHERE value->>'id'=NEW.expense_account::text;SELECT value INTO l FROM jsonb_array_elements(s#>'{accounting,accounts}') WHERE value->>'id'=NEW.liability_account::text;a=s#>'{accounting,period}';
 IF e IS NULL OR l IS NULL OR e->>'kind'<>'expense' OR e->>'role'<>'expense' OR l->>'kind'<>'liability' OR l->>'role'<>'payable' OR e->'active'<>'true'::jsonb OR l->'active'<>'true'::jsonb OR(e->>'version')::integer<>NEW.expense_version OR(l->>'version')::integer<>NEW.liability_version OR e->>'currencyId'<>NEW.currency_id::text OR l->>'currencyId'<>NEW.currency_id::text OR(e->>'unitScale')::integer<>NEW.unit_scale OR(l->>'unitScale')::integer<>NEW.unit_scale OR(e->>'hubId' IS NOT NULL AND(e->>'hubId')::uuid IS DISTINCT FROM NEW.hub_id) OR(l->>'hubId' IS NOT NULL AND(l->>'hubId')::uuid IS DISTINCT FROM NEW.hub_id) OR(a->>'version')::integer<>NEW.period_version OR a->>'state'<>'open' OR NEW.posted_on NOT BETWEEN(a->>'startsOn')::date AND(a->>'endsOn')::date OR(a->>'closedThrough' IS NOT NULL AND NEW.posted_on<=(a->>'closedThrough')::date) THEN RAISE EXCEPTION 'TUITION_COLLECTION_MAPPING_INVALID' USING ERRCODE='23514';END IF;RETURN NEW;
END $$;
CREATE TRIGGER tuition_collection_record_guard BEFORE INSERT OR UPDATE ON public.payroll_tuition_collection_accruals FOR EACH ROW EXECUTE FUNCTION public.tuition_collection_record_guard();
CREATE FUNCTION public.tuition_collection_void_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE p record;s jsonb;w jsonb;target jsonb;BEGIN
 -- The retained gross-correction body is shared with salary corrections.
 IF NOT public.salary_input_valid(NEW.input,true) OR(NEW.input->>'accrualId')::uuid IS DISTINCT FROM NEW.accrual_id THEN RAISE EXCEPTION 'TUITION_COLLECTION_INPUT_INVALID' USING ERRCODE='23514';END IF;
 s=public.tuition_collection_void_source(NEW.accrual_id,(NEW.input#>>'{period,id}')::uuid);w=s#>'{current,work}';SELECT * INTO p FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id;
 target=jsonb_build_object('all',false,'hubs','[]'::jsonb,'people',jsonb_build_array(jsonb_build_object('id',w->>'personId','hubId',w->'hubId')),'workContext',jsonb_build_object('personId',w->>'personId','hubId',w->'hubId'));
 IF s IS NULL OR s ? 'unavailable' OR p.id IS NULL OR p.status<>'pending' OR p.action IS DISTINCT FROM 'work.tuition_collection.void' OR p.target_id IS DISTINCT FROM NEW.id OR p.target_version IS DISTINCT FROM 0 OR p.privacy_capability IS DISTINCT FROM 'payroll-accruals.view' OR p.scope IS DISTINCT FROM target OR p.payload IS DISTINCT FROM NEW.input OR p.review_context IS DISTINCT FROM s OR NEW.source_snapshot IS DISTINCT FROM s OR s#>>'{before,voidId}' IS NOT NULL OR NOT public.report_comment_human_verified(NEW.created_by) OR(NEW.input#>>'{period,version}')::integer IS DISTINCT FROM(s#>>'{current,period,version}')::integer OR(NEW.input->>'postedOn')::date<(s#>>'{before,postedOn}')::date THEN RAISE EXCEPTION 'TUITION_COLLECTION_VOID_REVIEW_REQUIRED' USING ERRCODE='23514';END IF;
 IF NEW.created_by=(s#>>'{before,personId}')::uuid AND NOT EXISTS(SELECT 1 FROM public.academies WHERE id=NEW.academy_id AND master_person_id=NEW.created_by) THEN RAISE EXCEPTION 'BENEFICIARY_REVIEW_FORBIDDEN' USING ERRCODE='23514';END IF;NEW.journal_id=CASE WHEN(s#>>'{before,grossMinor}')::numeric>0 THEN NEW.id ELSE NULL END;NEW.posted_on=(NEW.input->>'postedOn')::date;IF s#>>'{current,period,state}' IS DISTINCT FROM 'open' OR NEW.posted_on NOT BETWEEN(s#>>'{current,period,startsOn}')::date AND(s#>>'{current,period,endsOn}')::date OR(s#>>'{current,period,closedThrough}' IS NOT NULL AND NEW.posted_on<=(s#>>'{current,period,closedThrough}')::date) THEN RAISE EXCEPTION 'TUITION_COLLECTION_VOID_PERIOD_INVALID' USING ERRCODE='23514';END IF;NEW.created_at=clock_timestamp();RETURN NEW;
END $$;
CREATE TRIGGER tuition_collection_void_guard BEFORE INSERT ON public.payroll_tuition_collection_voids FOR EACH ROW EXECUTE FUNCTION public.tuition_collection_void_guard();
CREATE FUNCTION public.tuition_collection_posting_complete() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE j record;b record;s jsonb;n integer;BEGIN
 SELECT * INTO j FROM public.finance_journals WHERE academy_id=NEW.academy_id AND id=NEW.id;
 IF TG_TABLE_NAME='payroll_tuition_collection_accruals' THEN
  IF public.tuition_collection_accrual_source(NEW.input,NEW.id) IS DISTINCT FROM NEW.source_snapshot THEN RAISE EXCEPTION 'TUITION_COLLECTION_SOURCE_CHANGED' USING ERRCODE='23514';END IF;
  SELECT count(*) INTO n FROM public.payroll_tuition_collection_receipts q WHERE q.academy_id=NEW.academy_id AND q.accrual_id=NEW.id AND q.release_id IS NULL;
  IF n<>jsonb_array_length(NEW.input->'receiptIds') THEN RAISE EXCEPTION 'COLLECTION_RECEIPT_OWNERSHIP_REQUIRED' USING ERRCODE='23514';END IF;
  IF NEW.amount_minor=0 THEN IF NEW.journal_id IS NOT NULL OR j.id IS NOT NULL THEN RAISE EXCEPTION 'ZERO_COLLECTION_HAS_NO_LEDGER_POSTING' USING ERRCODE='23514';END IF;RETURN NULL;END IF;
  IF j.id IS NULL OR j.approval_id IS DISTINCT FROM NEW.approval_id OR j.posted_by IS DISTINCT FROM NEW.created_by OR j.period_id IS DISTINCT FROM NEW.period_id OR j.period_version IS DISTINCT FROM NEW.period_version OR j.posted_on IS DISTINCT FROM NEW.posted_on OR j.purpose IS DISTINCT FROM 'activity' OR j.line_count<>2 OR j.reverses_id IS NOT NULL OR j.description IS DISTINCT FROM 'Recorded collected tuition gross accrual' OR j.reference IS DISTINCT FROM 'PAYROLL-TUITION_COLLECTION' OR NOT EXISTS(SELECT 1 FROM public.finance_journal_lines WHERE academy_id=NEW.academy_id AND journal_id=NEW.id AND line_number=1 AND account_id=NEW.expense_account AND account_version=NEW.expense_version AND side='debit' AND amount_minor=NEW.amount_minor AND note='') OR NOT EXISTS(SELECT 1 FROM public.finance_journal_lines WHERE academy_id=NEW.academy_id AND journal_id=NEW.id AND line_number=2 AND account_id=NEW.liability_account AND account_version=NEW.liability_version AND side='credit' AND amount_minor=NEW.amount_minor AND note='') THEN RAISE EXCEPTION 'TUITION_COLLECTION_POSTING_REQUIRED' USING ERRCODE='23514';END IF;
 ELSE
  SELECT * INTO b FROM public.payroll_tuition_collection_accruals WHERE academy_id=NEW.academy_id AND id=NEW.accrual_id;
  IF b.void_id IS DISTINCT FROM NEW.id OR EXISTS(SELECT 1 FROM public.payroll_tuition_collection_receipts q WHERE q.academy_id=NEW.academy_id AND q.accrual_id=b.id AND q.release_id IS DISTINCT FROM NEW.id) THEN RAISE EXCEPTION 'COLLECTION_RECEIPT_RELEASE_REQUIRED' USING ERRCODE='23514';END IF;
  s=public.tuition_collection_void_source(NEW.accrual_id,(NEW.input#>>'{period,id}')::uuid);IF s IS NULL OR s ? 'unavailable' OR s->'current' IS DISTINCT FROM NEW.source_snapshot->'current' OR(s->'before')-'voidId' IS DISTINCT FROM(NEW.source_snapshot->'before')-'voidId' THEN RAISE EXCEPTION 'TUITION_COLLECTION_VOID_SOURCE_CHANGED' USING ERRCODE='23514';END IF;
  IF b.amount_minor=0 THEN IF NEW.journal_id IS NOT NULL OR j.id IS NOT NULL THEN RAISE EXCEPTION 'ZERO_COLLECTION_HAS_NO_LEDGER_POSTING' USING ERRCODE='23514';END IF;RETURN NULL;END IF;
  IF j.id IS NULL OR j.approval_id IS DISTINCT FROM NEW.approval_id OR j.posted_by IS DISTINCT FROM NEW.created_by OR j.period_id IS DISTINCT FROM(NEW.input#>>'{period,id}')::uuid OR j.period_version IS DISTINCT FROM(NEW.input#>>'{period,version}')::integer OR j.posted_on IS DISTINCT FROM NEW.posted_on OR j.purpose IS DISTINCT FROM 'activity' OR j.line_count<>2 OR j.reverses_id IS DISTINCT FROM b.id OR j.description IS DISTINCT FROM 'Correction of collected tuition gross accrual' OR j.reference IS DISTINCT FROM 'PAYROLL-TUITION_COLLECTION-CORRECTION' OR NOT EXISTS(SELECT 1 FROM public.finance_journal_lines WHERE academy_id=NEW.academy_id AND journal_id=NEW.id AND line_number=1 AND account_id=b.expense_account AND account_version=b.expense_version AND side='credit' AND amount_minor=b.amount_minor AND note='') OR NOT EXISTS(SELECT 1 FROM public.finance_journal_lines WHERE academy_id=NEW.academy_id AND journal_id=NEW.id AND line_number=2 AND account_id=b.liability_account AND account_version=b.liability_version AND side='debit' AND amount_minor=b.amount_minor AND note='') THEN RAISE EXCEPTION 'TUITION_COLLECTION_VOID_POSTING_REQUIRED' USING ERRCODE='23514';END IF;
 END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER tuition_collection_posting_complete AFTER INSERT ON public.payroll_tuition_collection_accruals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.tuition_collection_posting_complete();
CREATE CONSTRAINT TRIGGER tuition_collection_void_posting_complete AFTER INSERT ON public.payroll_tuition_collection_voids DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.tuition_collection_posting_complete();
CREATE CONSTRAINT TRIGGER tuition_collection_reviewed AFTER INSERT ON public.payroll_tuition_collection_accruals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.reviewed_approval_complete();
CREATE CONSTRAINT TRIGGER tuition_collection_void_reviewed AFTER INSERT ON public.payroll_tuition_collection_voids DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.reviewed_approval_complete();
CREATE FUNCTION public.tuition_collection_effect_required() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF NEW.status='applied' AND((NEW.action='work.tuition_collection.record' AND NOT EXISTS(SELECT 1 FROM public.payroll_tuition_collection_accruals WHERE academy_id=NEW.academy_id AND id=NEW.target_id AND approval_id=NEW.id AND created_by=NEW.reviewer_id)) OR(NEW.action='work.tuition_collection.void' AND NOT EXISTS(SELECT 1 FROM public.payroll_tuition_collection_voids WHERE academy_id=NEW.academy_id AND id=NEW.target_id AND approval_id=NEW.id AND created_by=NEW.reviewer_id))) THEN RAISE EXCEPTION 'TUITION_COLLECTION_EFFECT_REQUIRED' USING ERRCODE='23514';END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER tuition_collection_effect_required AFTER INSERT OR UPDATE ON public.approval_requests DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.tuition_collection_effect_required();
CREATE FUNCTION public.tuition_collection_reversal_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM public.payroll_tuition_collection_accruals WHERE academy_id=NEW.academy_id AND id=NEW.reverses_id) AND NOT EXISTS(SELECT 1 FROM public.payroll_tuition_collection_voids v JOIN public.approval_requests p ON p.academy_id=v.academy_id AND p.id=v.approval_id WHERE v.academy_id=NEW.academy_id AND v.id=NEW.id AND v.accrual_id=NEW.reverses_id AND p.action='work.tuition_collection.void' AND p.target_id=NEW.id AND p.payload=v.input AND NEW.approval_id=p.id) THEN RAISE EXCEPTION 'TUITION_COLLECTION_CORRECTION_WORKFLOW_REQUIRED' USING ERRCODE='23514';END IF;RETURN NEW;
END $$;
CREATE TRIGGER tuition_collection_reversal_guard BEFORE INSERT ON public.finance_journals FOR EACH ROW WHEN(NEW.reverses_id IS NOT NULL) EXECUTE FUNCTION public.tuition_collection_reversal_guard();
CREATE FUNCTION public.tuition_collection_approval_privacy() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE w record;b record;a record;s jsonb;ids uuid[];invoice_ref uuid;BEGIN
 IF NEW.action='work.tuition_collection.record' THEN invoice_ref=(NEW.payload->>'invoiceId')::uuid;SELECT * INTO w FROM public.work_engagements WHERE academy_id=NEW.academy_id AND id=(NEW.payload#>>'{engagement,id}')::uuid;ids=ARRAY[(NEW.payload#>>'{expenseAccount,id}')::uuid,(NEW.payload#>>'{liabilityAccount,id}')::uuid];
 ELSE SELECT * INTO b FROM public.payroll_tuition_collection_accruals WHERE academy_id=NEW.academy_id AND id=(NEW.payload->>'accrualId')::uuid;SELECT * INTO w FROM public.work_engagements WHERE academy_id=NEW.academy_id AND id=b.engagement_id;invoice_ref=b.invoice_id;ids=ARRAY[b.expense_account,b.liability_account];END IF;
 IF w.id IS NULL THEN NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('unresolved',true));RETURN NEW;END IF;
 s=jsonb_build_object('all',false,'hubs','[]'::jsonb,'people',jsonb_build_array(jsonb_build_object('id',w.person_id,'hubId',w.hub_id)),'workContext',jsonb_build_object('personId',w.person_id,'hubId',w.hub_id));NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('capability','work-pay.view','scope',s));
 FOR a IN SELECT id,hub_id FROM public.finance_accounts WHERE academy_id=NEW.academy_id AND id=ANY(ids) LOOP s=CASE WHEN a.hub_id IS NULL THEN jsonb_build_object('all',true,'hubs','[]'::jsonb) ELSE jsonb_build_object('all',false,'hubs',jsonb_build_array(a.hub_id)) END;NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('capability','accounts.view','scope',s),jsonb_build_object('capability','journals.view','scope',s));END LOOP;
 IF(SELECT count(*) FROM public.finance_accounts WHERE academy_id=NEW.academy_id AND id=ANY(ids))<>2 THEN NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('unresolved',true));END IF;
 SELECT x.id,x.hub_id,x.class_id,x.student_id INTO a FROM public.tuition_invoices x WHERE x.academy_id=NEW.academy_id AND x.id=invoice_ref;
 IF a.id IS NULL THEN NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('unresolved',true));ELSE
 s=jsonb_build_object('all',false,'hubs','[]'::jsonb,'classes',jsonb_build_array(jsonb_build_object('id',a.class_id,'hubId',a.hub_id)),'people',jsonb_build_array(jsonb_build_object('id',a.student_id,'hubId',a.hub_id)),'recordContext',jsonb_build_object('hubId',a.hub_id,'classId',a.class_id,'studentId',a.student_id));NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('capability','invoices.view','scope',s),jsonb_build_object('capability','receipts.view','scope',s));END IF;RETURN NEW;
 EXCEPTION WHEN invalid_text_representation THEN NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('unresolved',true));RETURN NEW;
END $$;
CREATE TRIGGER zz_tuition_collection_approval_privacy BEFORE INSERT ON public.approval_requests FOR EACH ROW WHEN(NEW.action IN('work.tuition_collection.record','work.tuition_collection.void')) EXECUTE FUNCTION public.tuition_collection_approval_privacy();
REVOKE ALL ON FUNCTION public.tuition_collection_input_valid(jsonb),public.tuition_collection_accrual_source(jsonb,uuid),public.tuition_collection_void_source(uuid,uuid),public.tuition_collection_record_guard(),public.tuition_collection_void_guard(),public.tuition_collection_posting_complete(),public.tuition_collection_effect_required(),public.tuition_collection_reversal_guard(),public.tuition_collection_approval_privacy() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.tuition_collection_input_valid(jsonb),public.tuition_collection_accrual_source(jsonb,uuid),public.tuition_collection_void_source(uuid,uuid) TO kavosh_runtime;
CREATE OR REPLACE FUNCTION public.tuition_course_accrual_source(i jsonb,p_exclude uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog SET DateStyle='ISO,YMD' AS $$ DECLARE tenant uuid:=nullif(current_setting('app.academy_id',true),'')::uuid;s jsonb;w jsonb;c jsonb;r record;t record;a record;floor_on date;BEGIN
 s=public.payroll_adjustment_source((i#>>'{engagement,id}')::uuid,(i->>'earnedOn')::date,(i#>>'{expenseAccount,id}')::uuid,(i#>>'{liabilityAccount,id}')::uuid,(i#>>'{period,id}')::uuid);IF s IS NULL THEN RETURN NULL;END IF;w=s->'work';
 IF(w->>'headerVersion')::integer<>(i#>>'{engagement,version}')::integer OR(w->>'termsVersion')::integer<>(i->>'termsVersion')::integer THEN RETURN jsonb_build_object('unavailable','WORK_TERMS_CHANGED');END IF;
 IF w->'active'<>'true'::jsonb OR w->>'classification' NOT IN('employee','contractor') OR(i->>'earnedOn')::date<(w->>'startsOn')::date OR(w->>'endsOn' IS NOT NULL AND(i->>'earnedOn')::date>(w->>'endsOn')::date) THEN RETURN jsonb_build_object('unavailable','EFFECTIVE_COMPENSATED_WORK_REQUIRED');END IF;
 SELECT * INTO r FROM public.work_engagement_revisions WHERE academy_id=tenant AND engagement_id=(w->>'id')::uuid AND version=(w->>'termsVersion')::integer;
 SELECT value INTO c FROM jsonb_array_elements(r.components) WHERE value->>'code'=i->>'componentCode' AND value->>'kind'='tuition_percentage' AND(i->>'earnedOn')::date>=(value->>'from')::date AND(value->>'through' IS NULL OR(i->>'earnedOn')::date<=(value->>'through')::date);
 IF c IS NULL OR c->>'basis' NOT IN('course_net','course_gross') THEN RETURN jsonb_build_object('unavailable','COURSE_PERCENTAGE_COMPONENT_REQUIRED');END IF;
 SELECT x.id,x.plan_id,x.plan_version,x.student_id,x.class_id,x.hub_id,x.credit_id,d.issued_on,p.currency_id,p.unit_scale,v.net_minor,v.gross_minor,v.supply_on INTO t FROM public.tuition_invoices x JOIN public.billing_documents d ON d.academy_id=x.academy_id AND d.id=x.id JOIN public.tuition_plans p ON p.academy_id=x.academy_id AND p.id=x.plan_id JOIN public.tuition_plan_revisions v ON v.academy_id=x.academy_id AND v.plan_id=x.plan_id AND v.version=x.plan_version WHERE x.academy_id=tenant AND x.id=(i->>'invoiceId')::uuid;
 IF t.id IS NULL THEN RETURN NULL;END IF;
 IF t.credit_id IS NOT NULL THEN RETURN jsonb_build_object('unavailable','CREDITED_TUITION_SOURCE_REQUIRES_REVIEW');END IF;
 IF t.currency_id::text<>w->>'currencyId' OR t.hub_id IS DISTINCT FROM(w->>'hubId')::uuid OR(i->>'earnedOn')::date<t.issued_on THEN RETURN jsonb_build_object('unavailable','TUITION_COURSE_SOURCE_MISMATCH');END IF;
 SELECT x.id,x.class_id,x.person_id,v.version,v.definition INTO a FROM public.class_staff x JOIN public.class_staff_revisions v ON v.academy_id=x.academy_id AND v.assignment_id=x.id AND v.version=(c#>>'{assignment,version}')::integer WHERE x.academy_id=tenant AND x.id=(c#>>'{assignment,id}')::uuid;
 IF a.id IS NULL OR a.class_id IS DISTINCT FROM t.class_id OR a.person_id::text IS DISTINCT FROM w->>'personId' OR a.definition->'active' IS DISTINCT FROM 'true'::jsonb OR(i->>'earnedOn')::date<(a.definition->>'startsOn')::date OR(a.definition->>'endsOn' IS NOT NULL AND(i->>'earnedOn')::date>(a.definition->>'endsOn')::date) THEN RETURN jsonb_build_object('unavailable','TUITION_COURSE_ASSIGNMENT_REQUIRED');END IF;
 IF EXISTS(SELECT 1 FROM public.payroll_tuition_session_accruals z WHERE z.academy_id=tenant AND z.engagement_id=(w->>'id')::uuid AND z.plan_id=t.plan_id AND z.void_id IS NULL) THEN RETURN jsonb_build_object('unavailable','TUITION_EARNING_BASIS_CONFLICT');END IF;
 IF EXISTS(SELECT 1 FROM public.payroll_tuition_course_accruals x WHERE x.academy_id=tenant AND x.engagement_id=(w->>'id')::uuid AND x.plan_id=t.plan_id AND x.void_id IS NULL AND(p_exclude IS NULL OR x.id<>p_exclude)) THEN RETURN jsonb_build_object('unavailable','TUITION_COURSE_ALREADY_ACCRUED');END IF;
 SELECT max(j.posted_on) INTO floor_on FROM public.payroll_tuition_course_accruals x JOIN public.finance_journals j ON j.academy_id=x.academy_id AND j.id=x.void_id WHERE x.academy_id=tenant AND x.engagement_id=(w->>'id')::uuid AND x.plan_id=t.plan_id AND x.void_id IS NOT NULL AND(p_exclude IS NULL OR x.id<>p_exclude);
 SELECT greatest(floor_on,max(j.posted_on)) INTO floor_on FROM public.payroll_tuition_session_accruals z JOIN public.finance_journals j ON j.academy_id=z.academy_id AND j.id=z.void_id WHERE z.academy_id=tenant AND z.engagement_id=(w->>'id')::uuid AND z.plan_id=t.plan_id AND z.void_id IS NOT NULL;
 IF EXISTS(SELECT 1 FROM public.payroll_tuition_collection_accruals z WHERE z.academy_id=tenant AND z.engagement_id=(w->>'id')::uuid AND z.plan_id=t.plan_id AND z.void_id IS NULL) THEN RETURN jsonb_build_object('unavailable','TUITION_EARNING_BASIS_CONFLICT');END IF;
 SELECT greatest(floor_on,max(v.posted_on)) INTO floor_on FROM public.payroll_tuition_collection_accruals z JOIN public.payroll_tuition_collection_voids v ON v.academy_id=z.academy_id AND v.id=z.void_id WHERE z.academy_id=tenant AND z.engagement_id=(w->>'id')::uuid AND z.plan_id=t.plan_id;
 RETURN jsonb_build_object('work',w,'accounting',s-'work','component',c,'tuition',jsonb_build_object('invoiceId',t.id,'planId',t.plan_id,'planVersion',t.plan_version,'studentId',t.student_id,'classId',t.class_id,'hubId',t.hub_id,'currencyId',t.currency_id,'unitScale',t.unit_scale,'netMinor',t.net_minor::text,'grossMinor',t.gross_minor::text,'issuedOn',t.issued_on::text,'supplyOn',t.supply_on::text,'assignmentId',a.id,'assignmentVersion',a.version,'assignment',a.definition),'grossMinor',round((CASE WHEN c->>'basis'='course_net' THEN t.net_minor ELSE t.gross_minor END)*power(10::numeric,(w->>'unitScale')::integer-t.unit_scale)*(c->>'percent')::numeric/100)::text,'releaseFloorOn',floor_on::text);
END $$;

CREATE OR REPLACE FUNCTION public.tuition_session_accrual_source(i jsonb,p_exclude uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog SET DateStyle='ISO,YMD' AS $$
DECLARE tenant uuid:=nullif(current_setting('app.academy_id',true),'')::uuid;s jsonb;w jsonb;c jsonb;r record;t record;a record;m record;x record;e record;line jsonb;fresh jsonb;service_on date;floor_on date;prefix numeric;part numeric;BEGIN
 SELECT h.version,v.input,v.source_snapshot INTO m FROM public.tuition_invoices inv JOIN public.tuition_session_allocations h ON h.academy_id=inv.academy_id AND h.plan_id=inv.plan_id JOIN public.tuition_session_allocation_revisions v ON v.academy_id=h.academy_id AND v.plan_id=h.plan_id AND v.version=h.version WHERE inv.academy_id=tenant AND inv.id=(i->>'invoiceId')::uuid;
 IF m.version IS NULL OR m.version<>(i->>'allocationVersion')::integer OR m.source_snapshot#>>'{invoice,id}' IS DISTINCT FROM i->>'invoiceId' THEN RETURN jsonb_build_object('unavailable','CURRENT_TUITION_SESSION_ALLOCATION_REQUIRED');END IF;
 SELECT value INTO line FROM jsonb_array_elements(m.source_snapshot->'sessions') WHERE value->>'sessionId'=i->>'sessionId';IF line IS NULL THEN RETURN jsonb_build_object('unavailable','ALLOCATED_TUITION_SESSION_REQUIRED');END IF;service_on=(line->>'on')::date;
 s=public.payroll_adjustment_source((i#>>'{engagement,id}')::uuid,service_on,(i#>>'{expenseAccount,id}')::uuid,(i#>>'{liabilityAccount,id}')::uuid,(i#>>'{period,id}')::uuid);IF s IS NULL THEN RETURN NULL;END IF;w=s->'work';
 fresh=public.tuition_session_allocation_source(m.input);IF fresh IS NULL OR NOT EXISTS(SELECT 1 FROM public.tuition_session_allocations h WHERE h.academy_id=tenant AND h.plan_id=(m.source_snapshot#>>'{invoice,planId}')::uuid AND h.version=m.version) THEN RETURN jsonb_build_object('unavailable','TUITION_ALLOCATION_CHANGED');END IF;
 IF(w->>'headerVersion')::integer<>(i#>>'{engagement,version}')::integer OR(w->>'termsVersion')::integer<>(i->>'termsVersion')::integer THEN RETURN jsonb_build_object('unavailable','WORK_TERMS_CHANGED');END IF;
 IF w->'active'<>'true'::jsonb OR w->>'classification' NOT IN('employee','contractor') OR service_on<(w->>'startsOn')::date OR(w->>'endsOn' IS NOT NULL AND service_on>(w->>'endsOn')::date) THEN RETURN jsonb_build_object('unavailable','EFFECTIVE_COMPENSATED_WORK_REQUIRED');END IF;
 SELECT * INTO r FROM public.work_engagement_revisions WHERE academy_id=tenant AND engagement_id=(w->>'id')::uuid AND version=(w->>'termsVersion')::integer;
 SELECT value INTO c FROM jsonb_array_elements(r.components) WHERE value->>'code'=i->>'componentCode' AND value->>'kind'='tuition_percentage' AND service_on>=(value->>'from')::date AND(value->>'through' IS NULL OR service_on<=(value->>'through')::date);
 IF c IS NULL OR c->>'basis' NOT IN('session_net','session_gross') THEN RETURN jsonb_build_object('unavailable','SESSION_PERCENTAGE_COMPONENT_REQUIRED');END IF;
 SELECT inv.id,inv.plan_id,inv.plan_version,inv.class_id,inv.hub_id,inv.student_id,inv.credit_id,d.issued_on,p.enrollment_id,p.currency_id,p.unit_scale,v.net_minor,v.gross_minor INTO t FROM public.tuition_invoices inv JOIN public.billing_documents d ON d.academy_id=inv.academy_id AND d.id=inv.id JOIN public.tuition_plans p ON p.academy_id=inv.academy_id AND p.id=inv.plan_id JOIN public.tuition_plan_revisions v ON v.academy_id=inv.academy_id AND v.plan_id=inv.plan_id AND v.version=inv.plan_version WHERE inv.academy_id=tenant AND inv.id=(i->>'invoiceId')::uuid;
 IF t.id IS NULL THEN RETURN NULL;END IF;IF t.credit_id IS NOT NULL THEN RETURN jsonb_build_object('unavailable','CREDITED_TUITION_SOURCE_REQUIRES_REVIEW');END IF;
 IF t.currency_id::text<>w->>'currencyId' OR t.hub_id IS DISTINCT FROM(w->>'hubId')::uuid OR(i->>'earnedOn')::date<greatest(service_on,t.issued_on) THEN RETURN jsonb_build_object('unavailable','TUITION_SESSION_SOURCE_MISMATCH');END IF;
 SELECT cs.id,cs.version,cs.status,cs.class_id,cs.starts_at,cs.ends_at,cs.time_info,cl.time_zone INTO x FROM public.class_sessions cs JOIN public.classes cl ON cl.academy_id=cs.academy_id AND cl.id=cs.class_id WHERE cs.academy_id=tenant AND cs.id=(i->>'sessionId')::uuid;
 SELECT id,version,joins_on,leaves_on,enabled INTO e FROM public.class_enrollments WHERE academy_id=tenant AND id=t.enrollment_id;
 IF x.id IS NULL OR x.class_id<>t.class_id OR x.status<>'scheduled' OR x.version<>(line->>'sessionVersion')::integer OR x.starts_at IS DISTINCT FROM(line->>'startsAt')::timestamptz OR x.ends_at IS DISTINCT FROM(line->>'endsAt')::timestamptz OR x.time_info->>'timeZone' IS DISTINCT FROM x.time_zone OR x.time_zone IS DISTINCT FROM m.source_snapshot#>>'{class,timeZone}' OR(x.starts_at AT TIME ZONE x.time_zone)::date<>service_on OR NOT e.enabled OR service_on<e.joins_on OR(e.leaves_on IS NOT NULL AND service_on>e.leaves_on) THEN RETURN jsonb_build_object('unavailable','ALLOCATED_SESSION_SOURCE_REVIEW_REQUIRED');END IF;
 SELECT cs.id,cs.class_id,cs.person_id,v.version,v.definition INTO a FROM public.class_staff cs JOIN public.class_staff_revisions v ON v.academy_id=cs.academy_id AND v.assignment_id=cs.id AND v.version=(c#>>'{assignment,version}')::integer WHERE cs.academy_id=tenant AND cs.id=(c#>>'{assignment,id}')::uuid;
 IF a.id IS NULL OR a.class_id<>t.class_id OR a.person_id::text IS DISTINCT FROM w->>'personId' OR a.definition->'active' IS DISTINCT FROM 'true'::jsonb OR service_on<(a.definition->>'startsOn')::date OR(a.definition->>'endsOn' IS NOT NULL AND service_on>(a.definition->>'endsOn')::date) THEN RETURN jsonb_build_object('unavailable','TUITION_SESSION_ASSIGNMENT_REQUIRED');END IF;
 IF EXISTS(SELECT 1 FROM public.payroll_tuition_course_accruals z WHERE z.academy_id=tenant AND z.engagement_id=(w->>'id')::uuid AND z.plan_id=t.plan_id AND z.void_id IS NULL) THEN RETURN jsonb_build_object('unavailable','TUITION_EARNING_BASIS_CONFLICT');END IF;
 IF EXISTS(SELECT 1 FROM public.payroll_tuition_session_accruals z WHERE z.academy_id=tenant AND z.engagement_id=(w->>'id')::uuid AND z.plan_id=t.plan_id AND z.session_id=x.id AND z.void_id IS NULL AND(p_exclude IS NULL OR z.id<>p_exclude)) THEN RETURN jsonb_build_object('unavailable','TUITION_SESSION_ALREADY_ACCRUED');END IF;
 SELECT max(q.posted_on) INTO floor_on FROM(SELECT j.posted_on FROM public.payroll_tuition_session_accruals z JOIN public.finance_journals j ON j.academy_id=z.academy_id AND j.id=z.void_id WHERE z.academy_id=tenant AND z.engagement_id=(w->>'id')::uuid AND z.plan_id=t.plan_id AND z.session_id=x.id AND z.void_id IS NOT NULL AND(p_exclude IS NULL OR z.id<>p_exclude) UNION ALL SELECT j.posted_on FROM public.payroll_tuition_course_accruals z JOIN public.finance_journals j ON j.academy_id=z.academy_id AND j.id=z.void_id WHERE z.academy_id=tenant AND z.engagement_id=(w->>'id')::uuid AND z.plan_id=t.plan_id AND z.void_id IS NOT NULL) q;
 prefix=(line->>CASE WHEN c->>'basis'='session_net' THEN 'netBefore' ELSE 'grossBefore' END)::numeric;part=(line->>CASE WHEN c->>'basis'='session_net' THEN 'netMinor' ELSE 'grossMinor' END)::numeric;
 IF EXISTS(SELECT 1 FROM public.payroll_tuition_collection_accruals z WHERE z.academy_id=tenant AND z.engagement_id=(w->>'id')::uuid AND z.plan_id=t.plan_id AND z.void_id IS NULL) THEN RETURN jsonb_build_object('unavailable','TUITION_EARNING_BASIS_CONFLICT');END IF;
 SELECT greatest(floor_on,max(v.posted_on)) INTO floor_on FROM public.payroll_tuition_collection_accruals z JOIN public.payroll_tuition_collection_voids v ON v.academy_id=z.academy_id AND v.id=z.void_id WHERE z.academy_id=tenant AND z.engagement_id=(w->>'id')::uuid AND z.plan_id=t.plan_id;
 RETURN jsonb_build_object('work',w,'accounting',s-'work','component',c,'tuition',jsonb_build_object('invoiceId',t.id,'planId',t.plan_id,'planVersion',t.plan_version,'studentId',t.student_id,'classId',t.class_id,'hubId',t.hub_id,'currencyId',t.currency_id,'unitScale',t.unit_scale,'netMinor',t.net_minor::text,'grossMinor',t.gross_minor::text,'issuedOn',t.issued_on::text,'assignmentId',a.id,'assignmentVersion',a.version,'assignment',a.definition,'enrollmentVersion',e.version),'allocation',jsonb_build_object('version',m.version,'sourceCurrent',NOT(fresh ? 'unavailable') AND fresh-'before'=m.source_snapshot-'before','selected',line,'policy',m.source_snapshot->'allocationPolicy'),'grossMinor',(round((prefix+part)*power(10::numeric,(w->>'unitScale')::integer-t.unit_scale)*(c->>'percent')::numeric/100)-round(prefix*power(10::numeric,(w->>'unitScale')::integer-t.unit_scale)*(c->>'percent')::numeric/100))::text,'releaseFloorOn',floor_on::text);
END $$;


CREATE OR REPLACE FUNCTION public.schema_revision() RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT 107 $$;


